      info1: { title: "Général" }, info2: { title: "Support" },
      info3: { title: "Entreprise", body: "Entrepreneur individuel Abdulkhamidov Daniiar Abdulkhamidovich (IP)<br/>12c ul. A. Karimova, Osh 723505, Kirghizistan" },
